JSON
{
  "headline": "فيلم كيميت: السنة الأولى.. مغامرة تاريخية وأكشن في 100 دقيقة",
  "intro": "يشهد عام 2026 إطلاق الفيلم المصري \"كيميت: السنة الأولى\" (Kemet: Year One)، وهو عمل يجمع بين طيات التاريخ وأجواء المغامرات الحافلة بالأكشن. يقدم هذا العمل تجربة سينمائية فريدة تستمر لمائة دقيقة، ويسلط الضوء على حقبة زمنية مليئة بالإثارة تحت رؤية فنية متكاملة لصانعه مو إسماعيل.",
  "overview": "يعيد فيلم \"كيميت: السنة الأولى\" (Kemet: Year One) صياغة تقديم الأعمال التاريخية العربية بنكهة مليئة بالحركة والمغامرات غير المسبوقة، ليضع المشاهدين في قلب الأحداث القديمة المليئة بالتحديات. يبتعد هذا العمل السينمائي عن طرق السرد الكلاسيكية التقليدية ليقدم بدلاً من ذلك وجبة بصرية ديناميكية تعتمد على الأكشن المستمر، مستفيداً من عنوانه الذي يحيل الجمهور مباشرة إلى الجذور العميقة للحضارة المصرية العريقة، مما يسهم في خلق عالم سينمائي مشوق يستكشف بدايات وأسرار تلك الحقبة الزمنية الغامضة.\n\nتتسم أجواء هذا الإصدار السينمائي بالحماس والتشويق المتصاعدين، حيث تم توظيف طاقات طاقم العمل وتشكيلة الممثلين لخلق مشاهد سينمائية تعتمد بشكل أساسي على المواجهات البدنية والمغامرات الملحمية الكبرى. ويعكس التصنيف الفني الذي ينتمي إليه العمل رغبة واضحة في تقديم رحلة بصرية متقنة تدمج بين الأصالة التاريخية لبيئة الأحداث والحركة السريعة المتقنة التي تجذب دوماً جمهور الشاشة الفضية الباحث عن الترفيه العالي المقرون بالعمق الزمني والمكاني المنتميين للأراضي المصرية.\n\nوما يميز مشروع \"كيميت\" بشكل خاص هو القيادة المزدوجة والمكثفة للفنان مو إسماعيل، الذي لم يكتفِ بتولي مهام التأليف والإخراج فقط، بل تصدر أيضاً قائمة الأبطال، ليعكس بذلك رؤية فنية متكاملة وموحدة تترجم أفكاره على الشاشة. ويقف إلى جانبه في تقديم هذه المغامرة التاريخية السينمائية فريق تمثيلي يضم كل من رسام سلامة، وأحمد التهامي، ومروان العزب، ليقدموا مجتمعين تجربة سينمائية مصرية خالصة تسعى جاهدة لحجز مكانتها الخاصة والمتميزة في ذاكرة السينما.",
  "highlights": [
    "تجربة سينمائية تدمج ببراعة بين السرد التاريخي والإيقاع السريع لمشاهد الأكشن والمغامرة.",
    "رؤية شاملة وموحدة للفنان مو إسماعيل الذي جمع بين مهام الإخراج والتأليف والبطولة.",
    "مشاركة مميزة لنجوم الحركة والدراما في عمل مصري خالص تمتد أحداثه لمائة دقيقة."
  ],
  "faq": [
    {
      "q": "من هو مخرج ومؤلف فيلم \"كيميت: السنة الأولى\"؟",
      "a": "تولى مو إسماعيل مهام إخراج وتأليف الفيلم، إلى جانب مشاركته في طاقم البطولة."
    },
    {
      "q": "إلى أي تصنيف ينتمي هذا العمل السينمائي؟",
      "a": "يصنف الفيلم كعمل تاريخي يجمع بين أجواء المغامرات ومشاهد الأكشن."
    },
    {
      "q": "كم تبلغ مدة الفيلم وفي أي عام تم إنتاجه؟",
      "a": "تبلغ مدة عرض الفيلم 100 دقيقة، وتم إصداره في عام 2026."
    }
  ]
}

