JSON
{
  "headline": "مسرحية أداجيو: سيمفونية درامية تستكشف خبايا النفس البشرية",
  "intro": "يشهد المشهد الفني المصري في عام 2026 إطلاق مسرحية \"أداجيو (اللحن الأخير)\"، وهو عمل درامي يجمع بين عمق المشاعر وتعقيدات النفس البشرية. من خلال رؤية إخراجية يقودها السعيد منسي وأحمد نبيل، وبتأليف الكاتب إبراهيم عبدالمجيد، يطل علينا نخبة من النجوم ليقدموا تجربة غنية بالتأملات الوجدانية والأبعاد الإنسانية.",
  "overview": "تغوص أحداث مسرحية \"أداجيو (اللحن الأخير)\" في أعماق الوجدان الإنساني المليء بالتناقضات، مقدمةً سردية درامية تتخذ من الإيقاع الموسيقي الهادئ والمشحون بالعاطفة إطاراً فنياً لها. تتشابك خيوط القصة لسرد حكاية غرامية مليئة بالتعقيدات الشديدة، حيث تبرز الصراعات الداخلية والاضطرابات الذهنية التي تواجه الأبطال في حياتهم. هذه التوليفة الدقيقة تضع المتلقي مباشرة أمام مرآة شفافة تعكس أصدق المشاعر الإنسانية وأكثرها شجناً وتأثيراً في الوجدان.\n\nتلعب الذاكرة دوراً محورياً وبارزاً في توجيه بوصلة الأحداث الدرامية، إذ تأخذ الشخصيات في رحلات ارتدادية عميقة نحو ماضٍ يلقي بظلاله الثقيلة على واقعهم الحاضر. تدفع هذه الاسترجاعات الزمنية أبطال القصة لاكتشاف مساحات خفية وغير ملموسة من وعيهم وذواتهم، مما يخلق حالة متفردة من التماهي مع أوجاعهم الدفينة ومحاولاتهم المستمرة للبحث عن الصدق الخالص المفقود وسط ضجيج المعاناة اليومية.\n\nيجسد هذا المزيج الذي صاغ كلماته إبراهيم عبدالمجيد حالة فنية متكاملة تعتمد بشكل رئيسي على الأداء التمثيلي القوي لإيصال رسالتها المعنوية. وبمشاركة طاقم تمثيلي متميز يضم كل من رامي الطنباري، وهبة عبدالغني، وبسمة شوقي، وجورج أشرف، ومحمد دياب، تتجسد أمام المشاهدين لوحة حية تلامس الروح والعقل معاً، ليكون \"اللحن الأخير\" بمثابة محطة تأملية عميقة تستكشف ماهية الحب الخالص، الألم النفسي، وحتمية المواجهة الذاتية.",
  "highlights": [
    "معالجة درامية عميقة تمزج ببراعة بين تعقيدات الحب والاضطرابات النفسية.",
    "رؤية إخراجية مشتركة تجمع بين إبداع المخرجين السعيد منسي وأحمد نبيل.",
    "نص أدبي مشوق من تأليف إبراهيم عبدالمجيد يغوص في تأثير الذكريات على الحاضر.",
    "طاقم تمثيلي متميز يضم نخبة من المواهب القادرة على تجسيد الشجن الإنساني بدقة."
  ],
  "faq": [
    {
      "q": "من هم أبطال مسرحية \"أداجيو (اللحن الأخير)\"؟",
      "a": "يشارك في بطولة العمل المسرحي كل من رامي الطنباري، هبة عبدالغني، بسمة شوقي، جورج أشرف، ومحمد دياب."
    },
    {
      "q": "من هو مؤلف هذا العمل الفني؟",
      "a": "المسرحية الدرامية من تأليف الكاتب إبراهيم عبدالمجيد."
    },
    {
      "q": "متى تم إنتاج المسرحية ومن تولى إخراجها؟",
      "a": "تم إنتاج المسرحية في مصر عام 2026، وتولى إخراجها الثنائي السعيد منسي وأحمد نبيل."
    }
  ]
